392: static int idma_run_window(struct idma_stream *v, struct idma_stream *a,
393: 			   u64 count, u64 deadline, bool measured, u64 *end_ns)
394: {
395: 	u64 completed = 0;
396: 	u32 spins = 0;
397: 	int ret;
398: 
399: 	if (!count)
400: 		return 0;
401: 	if (ktime_get_ns() >= deadline) {
402: 		ret = -ETIMEDOUT;
403: 		goto out;
404: 	}
405: 	if (signal_pending(current)) {
406: 		ret = -EINTR;
407: 		goto out;
408: 	}
409: 	ret = idma_submit(v, measured);
410: 	if (ret)
411: 		goto out;
412: 	for (;;) {
413: 		if (ktime_get_ns() >= deadline) {
414: 			ret = -ETIMEDOUT;
415: 			break;
416: 		}
417: 		if (signal_pending(current)) {
418: 			ret = -EINTR;
419: 			break;
420: 		}
421: 		ret = idma_poll(v, measured);
422: 		if (ret < 0)
423: 			break;
424: 		if (ret == 1) {
425: 			if (++completed == count) {
426: 				/* Capture V's end before polling/refilling A or taking snapshots. */
427: 				*end_ns = v->last_complete_ns;
428: 				return 0;
429: 			}
430: 			ret = idma_submit(v, measured);
431: 			if (ret)
432: 				break;
433: 		}
434: 		if (a) {
435: 			ret = idma_poll(a, measured);
436: 			if (ret < 0)
437: 				break;
438: 			if (ret == 1) {
439: 				ret = idma_submit(a, measured);
440: 				if (ret)
441: 					break;
442: 			}
443: 		}
444: 		if (!(++spins & 1023))
445: 			cond_resched();
446: 		cpu_relax();
447: 	}
448:  out:
449: 	*end_ns = ktime_get_ns();

519: /* Batch mode still uses DEFAULT read/write copies. STOP never cancels AXI. */
520: static int idma_batch_configure(struct idma_stream *s, u64 count)
521: {
522: 	void __iomem *base = s->idma->reg;
523: 
524: 	if (readq(base + IDMA_BATCH_MAGIC_OFFSET) != IDMA_BATCH_MAGIC)
525: 		return -EOPNOTSUPP;
526: 	if (readq(base + IDMA_BATCH_CONTROL_OFFSET) & 2)
527: 		return -EBUSY;
528: 	writeq(0, base + IDMA_BATCH_CONTROL_OFFSET);
529: 	writeq(count, base + IDMA_BATCH_TARGET_OFFSET);
530: 	writeq(s->size / PAGE_SIZE, base + IDMA_BATCH_PAGES_OFFSET);
531: 	writeq(1, base + IDMA_BATCH_CONTROL_OFFSET);
532: 	s->batch_configured = true;
533: 	s->next_offset = 0;
534: 	return readq(base + IDMA_BATCH_CONTROL_OFFSET) == 1 ? 0 : -EIO;
535: }
536: 
537: static void idma_batch_stop(struct idma_stream *s)
538: {
539: 	if (s && s->batch_configured && s->batch_started)
540: 		writeq(2, s->idma->reg + IDMA_BATCH_CONTROL_OFFSET);
541: }
542: 
543: static int idma_batch_collect(struct idma_stream *s)
544: {
545: 	u64 status, issued, completed;
546: 
547: 	if (!s || !s->batch_configured)
548: 		return 0;
549: 	if (s->retain)
550: 		return -EIO;
551: 	status = readq(s->idma->reg + IDMA_BATCH_CONTROL_OFFSET);
552: 	if (status & 2) {
553: 		idma_quarantine(s);
554: 		return -EIO;
555: 	}
556: 	if (s->batch_started) {
557: 		issued = readq(s->idma->reg + IDMA_BATCH_ISSUED_OFFSET);
558: 		completed = readq(s->idma->reg + IDMA_BATCH_COMPLETED_OFFSET);
559: 		s->stats->submitted = issued;
560: 		s->stats->completed = completed;
561: 		s->stats->completed_bytes = completed * PAGE_SIZE;
562: 		s->touched_end = max(s->touched_end,
563: 			(size_t)min(completed, (u64)(s->size / PAGE_SIZE)) * PAGE_SIZE);
564: 		if (issued != completed || issued > IDMA_EXPERIMENT_MAX_TRANSFERS)
565: 			return -EIO;
566: 	}
567: 	return status >> 32 ? -EIO : 0;
568: }
