576: static int idma_batch_window(struct idma_stream *v, struct idma_stream *a,
577: 			     u64 deadline, u64 *end_ns)
578: {
579: 	u32 spins = 0;
580: 	int ret;
581: 
582: 	if (ktime_get_ns() >= deadline) {
583: 		ret = -ETIMEDOUT;
584: 		goto out;
585: 	}
586: 	if (signal_pending(current)) {
587: 		ret = -EINTR;
588: 		goto out;
589: 	}
590: 	if (a) {
591: 		a->batch_started = true;
592: 		ret = idma_submit(a, false);
593: 		if (ret)
594: 			goto out;
595: 	}
596: 	v->batch_started = true;
597: 	ret = idma_submit(v, false);
598: 	if (ret)
599: 		goto out;
600: 	v->deadline_ns = deadline;
601: 	for (;;) {
602: 		if (ktime_get_ns() >= deadline) {
603: 			ret = -ETIMEDOUT;
604: 			break;
605: 		}
606: 		if (signal_pending(current)) {
607: 			ret = -EINTR;
608: 			break;
609: 		}
610: 		ret = idma_poll(v, false);
611: 		if (ret < 0)
612: 			break;
613: 		if (ret == 1) {
614: 			*end_ns = v->last_complete_ns;
615: 			return 0;
616: 		}
617: 		if (!(++spins & 1023))
618: 			cond_resched();
619: 		cpu_relax();
620: 	}
621:  out:
622: 	*end_ns = ktime_get_ns();
623: 	return ret;
624: }
