626: static void idma_snapshot(struct riscv_iommu_hpm_session *hpm,
627: 			  struct idma_stream *v, struct idma_stream *a,
628: 			  struct riscv_iommu_hpm_sample *sample, u64 active[2])
629: {
630: 	riscv_iommu_hpm_read(hpm, sample);
631: 	active[0] = readq(v->idma->reg + IDMA_ACTIVE_CYCLES_REG_OFFSET);
632: 	active[1] = a ? readq(a->idma->reg + IDMA_ACTIVE_CYCLES_REG_OFFSET) : 0;
633: }
