635: static void idma_snapshot_delta(struct idma_experiment_stats *stats, int n,
636: 			       const struct riscv_iommu_hpm_sample *before,
637: 			       const struct riscv_iommu_hpm_sample *after,
638: 			       u64 active_before, u64 active_after)
639: {
640: 	stats->active_cycles = active_after - active_before;
641: 	stats->iotlb_miss = after->iotlb_miss[n] - before->iotlb_miss[n];
642: 	stats->s1_ptw = after->s1_ptw[n] - before->s1_ptw[n];
643: 	stats->s2_ptw = after->s2_ptw[n] - before->s2_ptw[n];
644: }

738: static int idma_observation_finish(struct idma_observation *o,
739: 				   const struct idma_experiment *e, int run_error)
740: {
741: 	u64 values[IDMA_OBS_VALUES], path[16][8], status;
742: 	void __iomem *base;
743: 	bool valid;
744: 	int i;
745: 
746: 	if (!o->control || !o->armed)
747: 		return 0;
748: 	base = o->control->reg;
749: 	status = readq(base + IDMA_OBS_CONTROL_OFFSET);
750: 	if (status & 3) {
751: 		writeq(2, base + IDMA_OBS_CONTROL_OFFSET);
752: 		status = readq(base + IDMA_OBS_CONTROL_OFFSET);
753: 	}
754: 	for (i = 0; i < IDMA_OBS_VALUES; i++) {
755: 		writeq(i, base + IDMA_OBS_INDEX_OFFSET);
756: 		values[i] = readq(base + IDMA_OBS_DATA_OFFSET);
757: 	}
758: 	valid = !run_error && status == 4 &&
759: 		values[7] == e->victim_transfers && values[8] == values[7] &&
760: 		values[9] == (o->batch ? 1 : values[7]) &&
761: 		values[0] == values[1] + values[2] + values[3] &&
762: 		values[0] == values[10] + values[11] + values[12] + values[13];
763: 	/* Opening stock + accepted requests must equal returns + closing stock. */
764: 	for (i = 0; i < 2; i++) {
765: 		u64 opening = values[30 + i], closing = values[32 + i];
766: 
767: 		if ((opening >> 16) + values[14 + 6 * i] !=
768: 		    (closing >> 16) + values[16 + 6 * i] ||
769: 		    (opening & 0xffff) + values[15 + 6 * i] !=
770: 		    (closing & 0xffff) + values[17 + 6 * i])
771: 			valid = false;
772: 	}
773: 	if (o->path) {
774: 		int lane, stage, field;
775: 
776: 		for (i = 0; i < 16; i++)
777: 			for (field = 0; field < 8; field++) {
778: 				writeq(64 + i * 8 + field, base + IDMA_OBS_INDEX_OFFSET);
779: 				path[i][field] = readq(base + IDMA_OBS_DATA_OFFSET);
780: 			}
781: 		for (lane = 0; lane < 4; lane++) {
782: 			for (stage = 0; stage < 4; stage++) {
783: 				u64 *p = path[lane * 4 + stage];
784: 
785: 				/* Opening + entered = completed + closing, including carry-in. */
786: 				if (p[5] + p[0] != p[1] + p[2] + p[6] ||
787: 				    p[4] > p[3] || (!p[1] && (p[3] || p[4])) ||
788: 				    (stage < 3 && p[1] + p[2] != path[lane * 4 + stage + 1][0]))
789: 					valid = false;
790: 				/* All V transactions must be wholly inside the batch window. */
791: 				if (lane < 2 && (p[5] || p[6] || p[2] ||
792: 				    p[1] != values[14 + lane] || p[7] != p[3]))
793: 					valid = false;
794: 				if (lane >= 2 && e->aggressor_did == IDMA_EXPERIMENT_NO_AGGRESSOR)
795: 					for (field = 0; field < 8; field++)
796: 						if (p[field])
797: 							valid = false;
798: 			}
799: 		}
800: 		if (!values[14] || !values[15])
801: 			valid = false;
802: 	}

843: static long idma_run_experiment_mode(struct idma_device *victim,
844: 			       struct idma_experiment __user *uarg, bool batch)
845: {
846: 	struct idma_experiment e;
847: 	struct idma_stream streams[2] = {};
848: 	struct idma_observation observation = { .batch = batch };
849: 	struct idma_stream *v = &streams[0], *a = NULL;
850: 	struct idma_device *aggressor = NULL;
851: 	struct riscv_iommu_hpm_session *hpm = NULL;
852: 	struct riscv_iommu_hpm_sample before, after;
853: 	u64 active_before[2], active_after[2];
854: 	u64 start, end = 0, deadline, stamp;
855: 	int ret, drain_ret, verify_ret, observation_ret;
856: 
857: 	if (copy_from_user(&e, uarg, sizeof(e)))
858: 		return -EFAULT;
859: 	memset(&e.status, 0, sizeof(e) - offsetof(struct idma_experiment, status));
860: 	e.victim_did = victim->did;
861: 	e.aggressor_did = IDMA_EXPERIMENT_NO_AGGRESSOR;
862: 	ret = idma_validate(&e);
863: 	if (!ret && batch && (e.chunk_bytes != PAGE_SIZE ||
864: 			      e.victim_transfers > IDMA_BATCH_MAX_TRANSFERS))
865: 		ret = -EINVAL;
866: 	if (ret)
867: 		goto out_copy;
868: 	ret = mutex_lock_interruptible(&idma_experiment_lock);
869: 	if (ret)
870: 		goto out_copy;
871: 	if (idma_any_quarantined()) {
872: 		ret = -EIO;
873: 		goto out_unlock;
874: 	}
875: 	if (e.aggressor_id != IDMA_EXPERIMENT_NO_AGGRESSOR) {
876: 		aggressor = idma_get_instance(e.aggressor_id);
877: 		if (!aggressor) {
878: 			ret = -ENODEV;
879: 			goto out_unlock;
880: 		}
881: 		if (aggressor == victim || aggressor->did == victim->did) {
882: 			ret = -EINVAL;
883: 			goto out_put;
884: 		}
885: 		e.aggressor_did = aggressor->did;
886: 		a = &streams[1];
887: 	}
888: 	ret = idma_observation_prepare(&observation, batch || READ_ONCE(idma_observe));
889: 	if (ret)
890: 		goto out_put;
891: 	if (batch && (readq(victim->reg + IDMA_BATCH_MAGIC_OFFSET) != IDMA_BATCH_MAGIC ||
892: 	    (aggressor && readq(aggressor->reg + IDMA_BATCH_MAGIC_OFFSET) != IDMA_BATCH_MAGIC))) {
893: 		ret = -EOPNOTSUPP;
894: 		goto out_put;
895: 	}
896: 	if (batch && ((readq(victim->reg + IDMA_BATCH_CONTROL_OFFSET) & 2) ||
897: 	    (aggressor && (readq(aggressor->reg + IDMA_BATCH_CONTROL_OFFSET) & 2)))) {
898: 		ret = -EBUSY;
899: 		goto out_put;
900: 	}
901: 	ret = idma_stream_prepare(v, victim, e.victim_pages, e.chunk_bytes, &e.victim);
902: 	if (ret)
903: 		goto out_cleanup;
904: 	if (a) {
905: 		ret = idma_stream_prepare(a, aggressor, e.aggressor_pages,
906: 					  e.chunk_bytes, &e.aggressor);
907: 		if (ret)
908: 			goto out_cleanup;
909: 	}
910: 	ret = riscv_iommu_hpm_acquire(v->dev, a ? a->dev : NULL, &hpm);

934: 	if (batch) {
935: 		/* Software warmup is drained before enabling the autonomous mode. */
936: 		if (a) {
937: 			ret = idma_drain(a);
938: 			if (ret)
939: 				goto out_drain;
940: 		}
941: 		ret = idma_batch_configure(v, e.victim_transfers);
942: 		if (!ret && a)
943: 			ret = idma_batch_configure(a, IDMA_EXPERIMENT_MAX_TRANSFERS);
944: 		if (ret)
945: 			goto out_drain;
946: 	}
947: 	e.victim.in_flight_at_start = v->in_flight;
948: 	e.aggressor.in_flight_at_start = a && a->in_flight;
949: 	ret = idma_observation_arm(&observation, victim, aggressor, e.victim_transfers);
950: 	if (ret)
951: 		goto out_drain;
952: 	stamp = ktime_get_ns();
953: 	idma_snapshot(hpm, v, a, &before, active_before);
954: 	start = ktime_get_ns();
955: 	e.snapshot_before_ns = start - stamp;
956: 	e.measurement_started = 1;
957: 	ret = batch ? idma_batch_window(v, a, deadline, &end) :
958: 		idma_run_window(v, a, e.victim_transfers, deadline, true, &end);
959: 	e.victim_elapsed_ns = end - start;
960: 	e.measurement_complete = !ret;
961: 	e.victim.in_flight_at_end = v->in_flight;
962: 	e.aggressor.in_flight_at_end = a && a->in_flight;
963: 	/* Stop autonomous A after V observation; hardware window is already frozen. */
964: 	if (batch) {
965: 		idma_batch_stop(a);
966: 		if (ret)
967: 			idma_batch_stop(v);
968: 	}
969: 	/* No more software A refills after V's final observed completion. */
970: 	idma_snapshot(hpm, v, a, &after, active_after);
971: 	e.snapshot_after_ns = ktime_get_ns() - end;
972: 	idma_snapshot_delta(&e.victim, 0, &before, &after,
973: 			    active_before[0], active_after[0]);
974: 	if (a)
975: 		idma_snapshot_delta(&e.aggressor, 1, &before, &after,
976: 				    active_before[1], active_after[1]);
977:  out_drain:
978: 	if (batch) {
979: 		idma_batch_stop(v);
980: 		idma_batch_stop(a);
981: 	}
982: 	stamp = ktime_get_ns();
983: 	drain_ret = idma_drain(v);
984: 	if (drain_ret && !ret)
985: 		ret = drain_ret;
986: 	if (a) {
987: 		drain_ret = idma_drain(a);
988: 		if (drain_ret && !ret)
989: 			ret = drain_ret;
990: 	}
991: 	e.drain_ns = ktime_get_ns() - stamp;
992: 	if (batch) {
993: 		drain_ret = idma_batch_collect(v);
994: 		if (drain_ret && !ret)
995: 			ret = drain_ret;
996: 		drain_ret = idma_batch_collect(a);
997: 		if (drain_ret && !ret)
998: 			ret = drain_ret;
999: 		if (!ret && e.victim.completed != e.victim_transfers)
1000: 			ret = -EIO;
1001: 	}
1002: 	riscv_iommu_hpm_release(hpm);
1003: 	if (!ret) {
1004: 		/* Both lanes are drained: reacquire CPU visibility before any check. */
1005: 		local_flush_icache_all();
1006: 		verify_ret = idma_verify(v);
1007: 		if (verify_ret)
1008: 			ret = verify_ret;
1009: 		if (a) {
1010: 			verify_ret = idma_verify(a);
1011: 			if (verify_ret && !ret)
1012: 				ret = verify_ret;
1013: 		}
1014: 	}
1015:  out_cleanup:
1016: 	observation_ret = idma_observation_finish(&observation, &e, ret);
1017: 	if (observation_ret && !ret)
1018: 		ret = observation_ret;
1019: 	if (batch) {
1020: 		idma_batch_disable(v);
1021: 		idma_batch_disable(a);
1022: 	}
1023: 	if (a)
1024: 		idma_stream_cleanup(a);
1025: 	idma_stream_cleanup(v);
1026:  out_put:
1027: 	idma_put_instance(observation.control);
1028: 	idma_put_instance(aggressor);
1029:  out_unlock:
1030: 	mutex_unlock(&idma_experiment_lock);
1031:  out_copy:
1032: 	e.status = ret;
1033: 	if (copy_to_user(uarg, &e, sizeof(e)))
1034: 		return -EFAULT;

