8: #define IDMA_EXPERIMENT_ABI 1U
9: #define IDMA_EXPERIMENT_MAX_TRANSFERS (1ULL << 32)
10: #define IDMA_EXPERIMENT_NO_AGGRESSOR ((__u32)~0U)
11: #define IDMA_EXPERIMENT_CAP_DID_HPM (1U << 0)
12: #define IDMA_EXPERIMENT_CAP_SW_REFILL (1U << 1)
13: #define IDMA_EXPERIMENT_CAP_HW_BATCH (1U << 2)
14: #define IDMA_BATCH_MAX_TRANSFERS (1ULL << 20)
15: /* HPM capability is preliminary; acquire checks slots/filter readback too. */
16: /* Neither capability nor configuration establishes board calibration. */
17: struct idma_experiment_caps {
18: 	__u32 abi_version;
19: 	__u32 struct_size;
20: 	__u32 capabilities;
21: 	__u32 device_id;
22: 	__u32 did;
23: 	__u32 max_pages;
24: 	__u32 page_bytes;
25: 	__u32 max_run_timeout_ms;
26: 	__u32 reserved[8];
27: };
