29: struct idma_experiment_stats {
30: 	__u64 submitted;
31: 	__u64 completed;
32: 	__u64 completed_bytes;
33: 	__u64 active_cycles;
34: 	__u64 iotlb_miss;
35: 	__u64 s1_ptw;
36: 	__u64 s2_ptw;
37: 	/* Observed completion to observed resubmission, incl. MMIO; not HW idle. */
38: 	__u64 refill_gap_ns_sum;
39: 	__u64 refill_gap_ns_max;
40: 	__u64 refill_gap_samples;
41: 	/* Submitted but not yet observed complete in software; not HW overlap. */
42: 	__u32 in_flight_at_start;
43: 	__u32 in_flight_at_end;
44: 	__u32 data_errors;
45: 	__u32 quarantined;
46: };
