48: struct idma_experiment {
49: 	/* Input: all reserved words and flags must be zero in ABI 1. */
50: 	__u32 abi_version;
51: 	__u32 struct_size;
52: 	__u32 flags;
53: 	__u32 aggressor_id;
54: 	__u32 victim_pages;
55: 	__u32 aggressor_pages;
56: 	__u32 chunk_bytes;
57: 	__u32 run_timeout_ms;
58: 	__u64 victim_transfers;
59: 	__u64 warmup_transfers;
60: 	__u32 reserved[8];
61: 	/* Output: status is a negative errno or zero, even when ioctl fails. */
62: 	__s32 status;
63: 	__u32 victim_did;
64: 	__u32 aggressor_did;
65: 	__u32 hpm_configured;
66: 	__u32 measurement_started;
67: 	__u32 measurement_complete;
68: 	__u64 victim_elapsed_ns;
69: 	/* Snapshot intervals bracket V's window; HPM is not an atomic snapshot. */
70: 	__u64 snapshot_before_ns;
71: 	__u64 snapshot_after_ns;
72: 	__u64 drain_ns;
73: 	struct idma_experiment_stats victim;
74: 	struct idma_experiment_stats aggressor;
75: };
